def _distance_m(lat1, lon1, lat2, lon2):
    """Distance orthodromique en mètres (version autonome pour la migration)."""
    phi1, phi2 = math.radians(lat1), math.radians(lat2)
    d_phi = math.radians(lat2 - lat1)
    d_lambda = math.radians(lon2 - lon1)
    a = (
        math.sin(d_phi / 2) ** 2
        + math.cos(phi1) * math.cos(phi2) * math.sin(d_lambda / 2) ** 2
    )
    return 2 * 6371008.8 * math.asin(math.sqrt(a))


def split_shared_stops(apps, schema_editor):
    """Donne à chaque arrêt de route sa propre fiche, rattachée à son école.

    Les anciens BusStop étaient globaux et réutilisés par leur nom : deux bus
    ou deux écoles pouvaient partager le même point GPS, déplacé à chaque
    recalcul. On duplique ici chaque arrêt de route, on le rattache à l'école
    du trajet et on associe chaque élève à l'arrêt le plus proche.
    """
    RouteStop = apps.get_model("routing", "RouteStop")
    BusStop = apps.get_model("routing", "BusStop")
    Student = apps.get_model("routing", "Student")

    route_ids = RouteStop.objects.values_list("route_id", flat=True).distinct()
    for route_id in route_ids:
        route_stops = list(
            RouteStop.objects.filter(route_id=route_id)
            .select_related("route", "stop")
            .order_by("order")
        )
        if not route_stops:
            continue
        school_id = route_stops[0].route.school_id
        if school_id is None:
            continue

        new_stops = []
        for route_stop in route_stops:
            old_stop = route_stop.stop
            new_stop = BusStop.objects.create(
                school_id=school_id,
                name=old_stop.name,
                latitude=old_stop.latitude,
                longitude=old_stop.longitude,
            )
            route_stop.stop_id = new_stop.pk
            route_stop.save(update_fields=["stop"])
            new_stops.append(new_stop)

        students = Student.objects.filter(
            assigned_route_id=route_id,
            latitude__isnull=False,
            longitude__isnull=False,
        )
        for student in students:
            nearest = min(
                new_stops,
                key=lambda stop: _distance_m(
                    student.latitude, student.longitude,
                    stop.latitude, stop.longitude,
                ),
            )
            student.bus_stop_id = nearest.pk
            student.save(update_fields=["bus_stop"])

    # Purge des anciens arrêts globaux devenus orphelins.
    for stop in BusStop.objects.filter(school__isnull=True):
        if not RouteStop.objects.filter(stop_id=stop.pk).exists():
            stop.delete()


